   116→// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
   117→// These hooks work with any strategy - the strategy is determined at runtime.
   118→// If silent is true, no output is printed (except backup notifications, which always print).
   119→// Returns the number of hooks that were installed (0 if all already up to date).
   120→func InstallGitHook(silent bool) (int, error) {
   121→	gitDir, err := GetGitDir()
   122→	if err != nil {
   123→		return 0, err
   124→	}
   125→
   126→	hooksDir := filepath.Join(gitDir, "hooks")
   127→	if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   128→		return 0, fmt.Errorf("failed to create hooks directory: %w", err)
   129→	}
   130→
   131→	// Determine command prefix based on local_dev setting
   132→	var cmdPrefix string
   133→	if isLocalDev() {
   134→		cmdPrefix = "go run ./cmd/entire/main.go"
   135→	} else {
   136→		cmdPrefix = "entire"
   137→	}
   138→
   139→	specs := buildHookSpecs(cmdPrefix)
   140→	installedCount := 0
   141→
   142→	for _, spec := range specs {
   143→		hookPath := filepath.Join(hooksDir, spec.name)
   144→		backupPath := hookPath + backupSuffix
   145→
   146→		content := spec.content
   147→		backupExists := fileExists(backupPath)
   148→
   149→		existing, existingErr := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   150→		hookExists := existingErr == nil
   151→
   152→		if hookExists && strings.Contains(string(existing), entireHookMarker) {
   153→			// Our hook is already installed - update content if backup exists (chain call may be needed)
   154→			if backupExists {
   155→				content = generateChainedContent(spec.content, spec.name)
   156→			}
   157→		} else if hookExists {
   158→			// Custom hook exists that isn't ours - back it up
   159→			if !backupExists {
   160→				if err := os.Rename(hookPath, backupPath); err != nil {
   161→					return installedCount, fmt.Errorf("failed to back up %s: %w", spec.name, err)
   162→				}
   163→				fmt.Fprintf(os.Stderr, "[entire] Backed up existing %s to %s%s\n", spec.name, spec.name, backupSuffix)
   164→			}
   165→			content = generateChainedContent(spec.content, spec.name)
   166→		}
   167→
   168→		// If backup exists but hook doesn't (or hook is ours without chain), ensure chain call
   169→		if backupExists && !hookExists {
   170→			content = generateChainedContent(spec.content, spec.name)
   171→		}
   172→
   173→		written, err := writeHookFile(hookPath, content)
   174→		if err != nil {
   175→			return installedCount, fmt.Errorf("failed to install %s hook: %w", spec.name, err)
   176→		}
   177→		if written {
   178→			installedCount++
   179→		}
   180→	}
   181→
   182→	if !silent {
   183→		fmt.Println("✓ Installed git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
   184→		fmt.Println("  Hooks delegate to the current strategy at runtime")
   185→	}
   186→
   187→	return installedCount, nil
   188→}
