   190→// writeHookFile writes a hook file if it doesn't exist or has different content.
   191→// Returns true if the file was written, false if it already had the same content.
   192→func writeHookFile(path, content string) (bool, error) {
   193→	// Check if file already exists with same content
   194→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
   195→	if err == nil && string(existing) == content {
   196→		return false, nil // Already up to date
   197→	}
   198→
   199→	// Git hooks must be executable (0o755)
   200→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   201→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
   202→	}
   203→	return true, nil
   204→}
   205→
   206→// RemoveGitHook removes all Entire CLI git hooks from the repository.
   207→// If a .pre-entire backup exists, it is restored. Moved hooks (.pre-*) containing
   208→// the Entire marker are also cleaned up.
   209→// Returns the number of hooks removed.
   210→func RemoveGitHook() (int, error) {
   211→	gitDir, err := GetGitDir()
   212→	if err != nil {
   213→		return 0, err
   214→	}
   215→
   216→	hooksDir := filepath.Join(gitDir, "hooks")
   217→	removed := 0
   218→	var removeErrors []string
   219→
   220→	for _, hook := range gitHookNames {
   221→		hookPath := filepath.Join(hooksDir, hook)
   222→		backupPath := hookPath + backupSuffix
   223→
   224→		// Remove the hook if it contains our marker
   225→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   226→		if err == nil && strings.Contains(string(data), entireHookMarker) {
   227→			if err := os.Remove(hookPath); err != nil {
   228→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
   229→				continue
   230→			}
   231→			removed++
   232→		}
   233→
   234→		// Restore .pre-entire backup if it exists
   235→		if fileExists(backupPath) {
   236→			if err := os.Rename(backupPath, hookPath); err != nil {
   237→				removeErrors = append(removeErrors, fmt.Sprintf("restore %s%s: %v", hook, backupSuffix, err))
   238→			}
   239→		}
   240→
   241→		// Clean up moved hooks (.pre-*) that contain our marker
   242→		movedHooks := scanForMovedHooks(hooksDir, hook)
   243→		for _, moved := range movedHooks {
   244→			if err := os.Remove(moved); err != nil {
   245→				removeErrors = append(removeErrors, fmt.Sprintf("cleanup %s: %v", filepath.Base(moved), err))
   246→			}
   247→		}
   248→	}
   249→
   250→	if len(removeErrors) > 0 {
   251→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
   252→	}
   253→	return removed, nil
   254→}
   255→
   256→// generateChainedContent appends a chain call to the base hook content,
   257→// so the pre-existing hook (backed up to .pre-entire) is called after our hook.
   258→func generateChainedContent(baseContent, hookName string) string {
   259→	return baseContent + fmt.Sprintf(`%s
   260→_entire_hook_dir="$(dirname "$0")"
   261→if [ -x "$_entire_hook_dir/%s%s" ]; then
   262→    "$_entire_hook_dir/%s%s" "$@"
   263→fi
   264→`, chainComment, hookName, backupSuffix, hookName, backupSuffix)
   265→}
   266→
   267→// scanForMovedHooks finds <hook>.pre-* files (excluding .pre-entire) that contain
   268→// the Entire hook marker. These are hooks that another tool moved aside using
   269→// the same backup pattern.
   270→func scanForMovedHooks(hooksDir, hookName string) []string {
   271→	pattern := filepath.Join(hooksDir, hookName+".pre-*")
   272→	matches, err := filepath.Glob(pattern)
   273→	if err != nil {
   274→		return nil
   275→	}
   276→
   277→	var result []string
   278→	backupPath := filepath.Join(hooksDir, hookName+backupSuffix)
   279→	for _, match := range matches {
   280→		if match == backupPath {
   281→			continue // Skip our own backup
   282→		}
   283→		data, err := os.ReadFile(match) //nolint:gosec // path from controlled glob
   284→		if err != nil {
   285→			continue
   286→		}
   287→		if strings.Contains(string(data), entireHookMarker) {
   288→			result = append(result, match)
   289→		}
   290→	}
   291→	return result
   292→}
