   294→// isLocalDev reads the local_dev setting from .entire/settings.json
   295→// Works correctly from any subdirectory within the repository.
   296→func isLocalDev() bool {
   297→	s, err := settings.Load()
   298→	if err != nil {
   299→		return false
   300→	}
   301→	return s.LocalDev
   302→}
